            const current = result[index];
            const next = result[index + 1];
            if (lineComment) {
                if (current === '\n') lineComment = false;
                continue;
            }
            if (blockComment) {
                if (current === '*' && next === '/') {
                    blockComment = false;
                    index++;
                }
                continue;
            }
            if (current === '/' && next === '/') {
                lineComment = true;
                index++;
                continue;
            }
            if (current === '/' && next === '*') {
                blockComment = true;
                index++;
                continue;
            }
            if (current === '{') braceDepth++;
