            uHeightMap: { type: 'sampler2D', value: null, expose: false },
            uEmissiveMap: { type: 'sampler2D', value: null, expose: false },
            uMetallicRoughnessMapScale: { type: 'vec2', value: new THREE.Vector2(1, 1), expose: false },
