            uSSRFresnelStrength: { type: 'float', value: valueFor('uSSRFresnelStrength', 0.45), expose: exposeAdvanced, advanced: true, min: 0.0, max: 1.0, step: 0.05, allow_higher: false, allow_lower: false },
