            const previousValue = this.normalizeElementLightingNormal(element[ELEMENT_LIGHTING_NORMAL_PROP]);
            if (previousValue === nextValue && element[ELEMENT_LIGHTING_NORMAL_PROP] === nextValue) return false;

            element[ELEMENT_LIGHTING_NORMAL_PROP] = nextValue;
            if (options.markDirty !== false) this.markProjectDirty();
