    const LightflowFrameResourceContracts = {
        create(texture, options = {}) {
            if (!texture) return null;
            return Object.freeze({
                texture,
                frameId: Math.max(0, Number(options.frameId) || 0),
                encoding: String(options.encoding || 'unknown'),
                width: Math.max(1, Number(options.width) || 1),
                height: Math.max(1, Number(options.height) || 1),
                space: String(options.space || 'unknown'),
                channels: options.channels ? String(options.channels) : null,
                aliasOf: options.aliasOf ? String(options.aliasOf) : null,
                cameraRevision: Math.max(0, Number(options.cameraRevision) || 0)
            });
        },

        validate(resource, expected = {}, label = 'frame_resource') {
            if (!resource?.texture) return false;
            const encodings = Array.isArray(expected.encoding)
                ? expected.encoding
                : expected.encoding ? [expected.encoding] : [];
            const valid = !(
                encodings.length && !encodings.includes(resource.encoding) ||
                expected.frameId !== undefined && resource.frameId !== expected.frameId ||
                expected.width !== undefined && resource.width !== expected.width ||
                expected.height !== undefined && resource.height !== expected.height ||
                expected.cameraRevision !== undefined &&
                    resource.cameraRevision !== expected.cameraRevision
            );
            if (!valid) {
                warnShaderArchitectOnce(
                    `resource_contract_${label}`,
                    `[Lightflow Frame Resources] Rejected incompatible ${label}.`,
                    { resource, expected }
                );
            }
            return valid;
        }
    };

    function getLightflowCameraRevision(camera) {
        let hash = 2166136261;
        [camera?.matrixWorldInverse, camera?.projectionMatrix].forEach(matrix => {
            (matrix?.elements || []).forEach(value => {
                const quantized = Math.round((Number(value) || 0) * 1000000);
                hash ^= quantized;
                hash = Math.imul(hash, 16777619);
            });
        });
        return hash >>> 0;
    }

