                bias: numberInRange(source.bias, defaults.bias, 0, 0.2),
                power: numberInRange(source.power, defaults.power, 0.25, 4),
                quality,
                renderScale: profile.renderScale,
                samples: profile.slices * profile.stepsPerSide * 2,
                slices: profile.slices,
                stepsPerSide: profile.stepsPerSide,
                hierarchyMode: profile.hierarchyMode,
