    /*
     * A Lightflow frame is one logical unit even though Three.js receives
     * several renderer.render() submissions. Keep observability at that level:
     * renderer.info is reset once, target switches are counted globally, and
     * timer-query results are consumed asynchronously without stalling WebGL.
     */
    const LightflowFrameBudgetController = {
        enabled: true,
        targetFps: 60,
        targetFpsExplicit: false,
        qualityLevels: [1.0, 0.82, 0.64, 0.5],
        qualityProfiles: [
            {
                sceneScale: 1.0, effectScale: 1.0,
                aoScale: 1.0, ssrScale: 1.0, atmosphereScale: 1.0,
                cloudScale: 1.0, bloomScale: 1.0
            },
            {
                sceneScale: 1.0, effectScale: 0.82,
                aoScale: 0.75, ssrScale: 0.78, atmosphereScale: 0.82,
                cloudScale: 0.78, bloomScale: 0.86
            },
            {
                sceneScale: 1.0, effectScale: 0.64,
                aoScale: 0.5, ssrScale: 0.58, atmosphereScale: 0.64,
                cloudScale: 0.56, bloomScale: 0.68
            },
            {
                sceneScale: 1.0, effectScale: 0.5,
                aoScale: 0.5, ssrScale: 0.45, atmosphereScale: 0.5,
                cloudScale: 0.42, bloomScale: 0.5
            }
        ],
        qualityIndex: 0,
        initialQualityIndex: 0,
        configuredRenderer: null,
        hardwareProfile: {
            classification: 'unknown', renderer: '', vendor: '',
            webgl2: false, maxTextureSize: 0, recommendedTargetFps: 60
        },
        averageGpuMs: 0,
        averageCpuMs: 0,
        averageFrameIntervalMs: 0,
        frameJitterMs: 0,
        sampleCount: 0,
        gpuSampleCount: 0,
        cooldown: 0,
        downPressure: 0,
        upPressure: 0,
        lastFrameTimestamp: 0,
        observedFrames: 0,
        droppedFrames: 0,
        lastBudgetSource: 'none',

        get qualityScale() {
            return this.qualityProfiles[this.qualityIndex]?.effectScale || 1;
        },

        get sceneScale() {
            return this.qualityProfiles[this.qualityIndex]?.sceneScale || 1;
        },

        get aoScale() {
            return this.qualityProfiles[this.qualityIndex]?.aoScale || 1;
        },

        get ssrScale() {
            return this.qualityProfiles[this.qualityIndex]?.ssrScale || 1;
        },

        get atmosphereScale() {
            return this.qualityProfiles[this.qualityIndex]?.atmosphereScale || 1;
        },

        get cloudScale() {
            return this.qualityProfiles[this.qualityIndex]?.cloudScale || 1;
        },

        get bloomScale() {
            return this.qualityProfiles[this.qualityIndex]?.bloomScale || 1;
        },

        classifyRenderer(renderer) {
            const gl = renderer?.getContext?.();
            if (!gl) return {
                classification: 'unknown', renderer: '', vendor: '',
                webgl2: false, maxTextureSize: 0, recommendedTargetFps: 60
            };
            let debugInfo = null;
            try { debugInfo = gl.getExtension?.('WEBGL_debug_renderer_info'); }
            catch (error) { debugInfo = null; }
            const read = (parameter, fallback = '') => {
                try { return gl.getParameter(parameter) || fallback; }
                catch (error) { return fallback; }
            };
            const vendor = String(read(
                debugInfo?.UNMASKED_VENDOR_WEBGL ?? gl.VENDOR,
                ''
            ));
            const rendererName = String(read(
                debugInfo?.UNMASKED_RENDERER_WEBGL ?? gl.RENDERER,
                ''
            ));
            const text = `${vendor} ${rendererName}`.toLowerCase();
            /*
             * Blockbench's plugin sandbox can hide Node/process even in the
             * desktop Electron build. Treat the host API and user agent as
             * authoritative fallbacks so a dedicated desktop GPU does not
             * inherit the conservative Web profile.
             */
            const desktopRuntime = !!(
                (typeof Blockbench !== 'undefined' && Blockbench?.isApp === true) ||
                (typeof process !== 'undefined' && process?.versions?.electron) ||
                (
                    typeof navigator !== 'undefined' &&
                    /(?:electron|blockbench)/i.test(String(navigator.userAgent || ''))
                )
            );
            const browserRuntime = !desktopRuntime;
            let classification = 'unknown';
            if (/swiftshader|software|llvmpipe|warp|microsoft basic/.test(text)) {
                classification = 'software';
            } else if (browserRuntime) {
                classification = 'web';
            } else if (/nvidia|geforce|rtx|gtx|quadro|tesla|radeon rx|radeon pro|\brx\s*\d|intel\(r\) arc|arc\(tm\)/.test(text)) {
                classification = 'dedicated';
            } else if (/intel|uhd|iris|hd graphics|integrated|radeon graphics|vega|apple/.test(text)) {
                classification = 'integrated';
            }
            const recommendedTargetFps = classification === 'software'
                ? 30
                : classification === 'web' ? 45 : 60;
            return {
                classification,
                renderer: rendererName,
                vendor,
                webgl2: !!renderer?.capabilities?.isWebGL2,
                maxTextureSize: Number(read(gl.MAX_TEXTURE_SIZE, 0)) || 0,
                recommendedTargetFps
            };
        },

        configureForRenderer(renderer, force = false) {
            if (!renderer || (!force && this.configuredRenderer === renderer)) {
                return this.hardwareProfile;
            }
            this.configuredRenderer = renderer;
            this.hardwareProfile = this.classifyRenderer(renderer);
            const classification = this.hardwareProfile.classification;
            this.initialQualityIndex = classification === 'software'
                ? 2
                : (classification === 'integrated' || classification === 'web' || classification === 'unknown')
                    ? 1
                    : 0;
            if (!this.targetFpsExplicit) {
                this.targetFps = this.hardwareProfile.recommendedTargetFps;
            }
            this.qualityIndex = this.enabled ? this.initialQualityIndex : 0;
            const tuning = {
                dedicated: { cacheMB: 96, warmJobs: 4, submissions: 2, submitMs: 4 },
                integrated: { cacheMB: 48, warmJobs: 3, submissions: 2, submitMs: 3 },
                web: { cacheMB: 32, warmJobs: 2, submissions: 1, submitMs: 2 },
                software: { cacheMB: 16, warmJobs: 1, submissions: 1, submitMs: 1.5 },
                unknown: { cacheMB: 48, warmJobs: 2, submissions: 1, submitMs: 2.5 }
            }[classification] || { cacheMB: 48, warmJobs: 2, submissions: 1, submitMs: 2.5 };
            if (typeof ShaderEngine === 'object' && ShaderEngine) {
                ShaderEngine.renderBatchGeometryCacheLimit = tuning.cacheMB * 1024 * 1024;
                ShaderEngine.shaderWarmupMaxConcurrentJobs = tuning.warmJobs;
                ShaderEngine.shaderWarmupMaxSubmissionsPerFrame = tuning.submissions;
                ShaderEngine.shaderWarmupSubmissionBudgetMs = tuning.submitMs;
                ShaderEngine.trimRenderBatchGeometryCache?.();
            }
            this.reset(false);
            return this.hardwareProfile;
        },

        setTargetFps(value) {
            const fps = Math.max(30, Math.min(240, Math.round(Number(value) || 60)));
            this.targetFps = fps;
            this.targetFpsExplicit = true;
            this.reset();
            return fps;
        },

        setEnabled(enabled) {
            this.enabled = enabled !== false;
            if (!this.enabled) this.qualityIndex = 0;
            else this.qualityIndex = this.initialQualityIndex;
            this.reset(false);
            return this.enabled;
        },

        setQualityIndex(index, cause = 'frame_budget') {
            const next = Math.max(0, Math.min(this.qualityLevels.length - 1, Math.round(index)));
            if (next === this.qualityIndex) return false;
            this.qualityIndex = next;
            AmbientOcclusionManager.states.forEach(state => {
                state.aoContentKey = '';
                state.aoHistoryValid = false;
                state.convergedSamples = 0;
            });
            ShaderEngine?.requestPreviewRender?.({ cause });
            return true;
        },

        observeDuration(durationMs, source = 'gpu') {
            if (!this.enabled || !Number.isFinite(durationMs) || durationMs <= 0) return;
            const previousSource = this.lastBudgetSource;
            if (source === 'gpu') {
                const weight = this.gpuSampleCount ? 0.08 : 1;
                this.averageGpuMs = this.averageGpuMs * (1 - weight) + durationMs * weight;
                this.gpuSampleCount += 1;
            }
            if (previousSource !== 'none' && previousSource !== source) {
                this.downPressure = 0;
                this.upPressure = 0;
            }
            this.lastBudgetSource = source;
            this.sampleCount += 1;
            if (this.cooldown > 0) {
                this.cooldown -= 1;
                return;
            }
            if (this.sampleCount < 8) return;
            const budget = 1000 / Math.max(30, this.targetFps);
            const measured = source === 'gpu' ? this.averageGpuMs : this.averageCpuMs;
            if (measured > budget * 1.04) {
                this.downPressure += 1;
                this.upPressure = 0;
            } else if (measured < budget * 0.64) {
                this.upPressure += 1;
                this.downPressure = Math.max(0, this.downPressure - 1);
            } else {
                this.downPressure = Math.max(0, this.downPressure - 1);
                this.upPressure = Math.max(0, this.upPressure - 1);
            }
            if (this.downPressure >= 3) {
                if (this.setQualityIndex(this.qualityIndex + 1, 'frame_budget_down')) {
                    this.cooldown = 12;
                }
                this.downPressure = 0;
            } else if (this.upPressure >= 18) {
                if (this.setQualityIndex(this.qualityIndex - 1, 'frame_budget_up')) {
                    this.cooldown = 30;
                }
                this.upPressure = 0;
            }
        },

        observe(profile) {
            if (!Number.isFinite(profile?.gpuMs) || profile.gpuMs <= 0) return;
            this.observeDuration(profile.gpuMs, 'gpu');
        },

        observeFrame(profile) {
            if (!profile) return;
            const cpuMs = Math.max(0, Number(profile.cpuMs) || 0);
            const cpuWeight = this.observedFrames ? 0.08 : 1;
            this.averageCpuMs = this.averageCpuMs * (1 - cpuWeight) + cpuMs * cpuWeight;
            const timestamp = Number(profile.timestamp) || performance.now();
            const interval = this.lastFrameTimestamp > 0 ? timestamp - this.lastFrameTimestamp : 0;
            this.lastFrameTimestamp = timestamp;
            if (interval > 0 && interval < 250) {
                const frameWeight = this.observedFrames ? 0.06 : 1;
                this.averageFrameIntervalMs = this.averageFrameIntervalMs * (1 - frameWeight) + interval * frameWeight;
                const targetInterval = 1000 / Math.max(30, this.targetFps);
                this.frameJitterMs = this.frameJitterMs * (1 - frameWeight) +
                    Math.abs(interval - targetInterval) * frameWeight;
                if (interval > targetInterval * 1.5) this.droppedFrames += 1;
                this.observedFrames += 1;
            }
            if (!profile.gpuSupported || profile.gpuDisjoint) {
                this.observeDuration(cpuMs, 'cpu_fallback');
            }
        },

        reset(resetQuality = true) {
            this.averageGpuMs = 0;
            this.averageCpuMs = 0;
            this.averageFrameIntervalMs = 0;
            this.frameJitterMs = 0;
            this.sampleCount = 0;
            this.gpuSampleCount = 0;
            this.cooldown = 0;
            this.downPressure = 0;
            this.upPressure = 0;
            this.lastFrameTimestamp = 0;
            this.observedFrames = 0;
            this.droppedFrames = 0;
            this.lastBudgetSource = 'none';
            if (resetQuality) {
                this.setQualityIndex(this.enabled ? this.initialQualityIndex : 0, 'frame_budget_reset');
            }
        },

        snapshot() {
            return {
                enabled: this.enabled,
                targetFps: this.targetFps,
                targetGpuMs: 1000 / Math.max(30, this.targetFps),
                averageGpuMs: this.averageGpuMs || null,
                averageCpuMs: this.averageCpuMs || null,
                averageFrameIntervalMs: this.averageFrameIntervalMs || null,
                frameJitterMs: this.frameJitterMs || null,
                droppedFrames: this.droppedFrames,
                observedFrames: this.observedFrames,
                budgetSource: this.lastBudgetSource,
                gpuSamples: this.gpuSampleCount,
                qualityScale: this.qualityScale,
                sceneScale: this.sceneScale,
                aoScale: this.aoScale,
                ssrScale: this.ssrScale,
                atmosphereScale: this.atmosphereScale,
                cloudScale: this.cloudScale,
                bloomScale: this.bloomScale,
                profile: { ...this.qualityProfiles[this.qualityIndex] },
                qualityLevel: this.qualityIndex,
                initialQualityLevel: this.initialQualityIndex,
                hardwareProfile: { ...this.hardwareProfile }
            };
        }
    };

    const LightflowFrameProfiler = {
        states: new Map(),
        historyLimit: 120,
        mode: 'normal',
        normalGpuSampleInterval: 8,

        setMode(mode = 'normal') {
            const next = ['normal', 'cpu', 'inspector', 'deep'].includes(mode) ? mode : 'normal';
            this.mode = next;
            return next;
        },

        getState(preview) {
            if (!preview?.renderer) return null;
            let state = this.states.get(preview);
            if (state && state.renderer === preview.renderer) return state;
            if (state) this.disposeState(state);
            state = {
                preview,
                renderer: preview.renderer,
                active: false,
                depth: 0,
                frameId: 0,
                passes: [],
                history: [],
                pendingQueries: [],
                targetSwitches: 0,
                originalSetRenderTarget: null,
                hadOwnSetRenderTarget: false,
                previousInfoAutoReset: true,
                timer: null,
                gpuSupported: false,
                gpuDisjoint: false,
                capturePassCpu: false,
                captureDetailed: false,
                frameQuery: null,
                activeGpuQuery: null,
                contextLost: false,
                contextGeneration: 0,
                contextCanvas: null,
                onContextLost: null,
                onContextRestored: null
            };
            this.states.set(preview, state);
            this.attachContextListeners(state);
            return state;
        },

        attachContextListeners(state) {
            const canvas = state?.renderer?.domElement;
            if (!canvas?.addEventListener || state.contextCanvas === canvas) return;
            this.detachContextListeners(state);
            state.contextCanvas = canvas;
            state.onContextLost = () => {
                state.contextLost = true;
                state.contextGeneration += 1;
                if (state.originalSetRenderTarget && state.renderer?.setRenderTarget !== state.originalSetRenderTarget) {
                    if (state.hadOwnSetRenderTarget) state.renderer.setRenderTarget = state.originalSetRenderTarget;
                    else delete state.renderer.setRenderTarget;
                }
                state.originalSetRenderTarget = null;
                if (state.renderer?.info) state.renderer.info.autoReset = state.previousInfoAutoReset;
                // Every WebGLQuery and extension object is invalidated on context
                // loss. Do not call delete/end on the dead objects; simply drop all
                // JS references and let the restored context recreate them lazily.
                state.timer = null;
                state.pendingQueries.length = 0;
                state.activeGpuQuery = null;
                state.frameQuery = null;
                state.gpuSupported = false;
                state.gpuDisjoint = true;
                state.active = false;
                state.depth = 0;
                state.capturePassCpu = false;
                state.captureDetailed = false;
                ShaderEngine?.handleRendererContextLost?.(state.preview, state.renderer);
            };
            state.onContextRestored = () => {
                state.contextLost = false;
                state.contextGeneration += 1;
                if (state.originalSetRenderTarget && state.renderer?.setRenderTarget !== state.originalSetRenderTarget) {
                    if (state.hadOwnSetRenderTarget) state.renderer.setRenderTarget = state.originalSetRenderTarget;
                    else delete state.renderer.setRenderTarget;
                }
                state.originalSetRenderTarget = null;
                if (state.renderer?.info) state.renderer.info.autoReset = state.previousInfoAutoReset;
                state.timer = null;
                state.pendingQueries.length = 0;
                state.activeGpuQuery = null;
                state.frameQuery = null;
                state.gpuSupported = false;
                state.gpuDisjoint = false;
                state.active = false;
                state.depth = 0;
                state.capturePassCpu = false;
                state.captureDetailed = false;
                LightflowFrameBudgetController.configureForRenderer(state.renderer, true);
                // All WebGLObjects created by the lost context are invalid.
                // Drop manager states WITHOUT calling dispose() on those stale GL
                // objects; disposing them after restoration produced repeated
                // "object does not belong to this context" errors and secondary
                // rebuild instability. Three recreates its own internal state; the
                // Lightflow managers allocate fresh targets lazily on the next frame.
                try {
                    ScreenAccessManager?.states?.delete?.(state.preview);
                    ScreenSpaceReflectionManager?.states?.delete?.(state.preview);
                    AmbientOcclusionManager?.states?.delete?.(state.preview);
                    MinecraftPromotionalSilhouetteManager?.states?.delete?.(state.preview);
                    LightflowFramePipeline.lastCompiledPlan = null;
                } catch (error) {}
                const redraw = () => {
                    try {
                        const recoveryScheduled = ShaderEngine?.handleRendererContextRestored?.(
                            state.preview,
                            state.renderer
                        );
                        if (!recoveryScheduled) {
                            ShaderEngine?.requestPreviewRender?.({ cause: 'webgl_context_restored' });
                        }
                    } catch (error) {}
                };
                if (typeof requestAnimationFrame === 'function') requestAnimationFrame(redraw);
                else setTimeout(redraw, 0);
            };
            canvas.addEventListener('webglcontextlost', state.onContextLost, false);
            canvas.addEventListener('webglcontextrestored', state.onContextRestored, false);
        },

        detachContextListeners(state) {
            const canvas = state?.contextCanvas;
            if (canvas?.removeEventListener) {
                if (state.onContextLost) canvas.removeEventListener('webglcontextlost', state.onContextLost, false);
                if (state.onContextRestored) canvas.removeEventListener('webglcontextrestored', state.onContextRestored, false);
            }
            state.contextCanvas = null;
            state.onContextLost = null;
            state.onContextRestored = null;
        },

        timerStillValid(state) {
            const timer = state?.timer;
            const renderer = state?.renderer;
            const gl = renderer?.getContext?.();
            if (!timer || !gl || timer.gl !== gl || state.contextLost || gl.isContextLost?.()) return false;
            try {
                const currentExtension = gl.getExtension(timer.extensionName);
                return !!currentExtension && currentExtension === timer.ext;
            } catch (error) {
                return false;
            }
        },

        discardTimerState(state, deleteQueries = true) {
            if (!state) return;
            const timer = state.timer;
            const canDelete = !!(
                deleteQueries && timer && !state.contextLost &&
                !timer.gl?.isContextLost?.()
            );
            if (canDelete) {
                if (state.frameQuery) {
                    try { timer.remove(state.frameQuery); } catch (error) {}
                }
                state.pendingQueries.forEach(entry => {
                    try { timer.remove(entry.query); } catch (error) {}
                });
            }
            state.pendingQueries.length = 0;
            state.frameQuery = null;
            state.activeGpuQuery = null;
            state.timer = null;
            state.gpuSupported = false;
        },

        createTimer(renderer) {
            const gl = renderer?.getContext?.();
            if (!gl?.getExtension) return null;
            const webgl2 = gl.getExtension('EXT_disjoint_timer_query_webgl2');
            if (webgl2 && typeof gl.createQuery === 'function') {
                return {
                    gl,
                    ext: webgl2,
                    extensionName: 'EXT_disjoint_timer_query_webgl2',
                    target: webgl2.TIME_ELAPSED_EXT,
                    create: () => gl.createQuery(),
                    begin: query => gl.beginQuery(webgl2.TIME_ELAPSED_EXT, query),
                    end: () => gl.endQuery(webgl2.TIME_ELAPSED_EXT),
                    available: query => gl.isQuery?.(query) !== true ? true : gl.getQueryParameter(query, gl.QUERY_RESULT_AVAILABLE),
                    result: query => gl.isQuery?.(query) === true ? gl.getQueryParameter(query, gl.QUERY_RESULT) : 0,
                    remove: query => { if (gl.isQuery?.(query) === true) gl.deleteQuery(query); }
                };
            }
            const webgl1 = gl.getExtension('EXT_disjoint_timer_query');
            if (webgl1?.createQueryEXT) {
                return {
                    gl,
                    ext: webgl1,
                    extensionName: 'EXT_disjoint_timer_query',
                    target: webgl1.TIME_ELAPSED_EXT,
                    create: () => webgl1.createQueryEXT(),
                    begin: query => webgl1.beginQueryEXT(webgl1.TIME_ELAPSED_EXT, query),
                    end: () => webgl1.endQueryEXT(webgl1.TIME_ELAPSED_EXT),
                    available: query => webgl1.isQueryEXT?.(query) !== true ? true : webgl1.getQueryObjectEXT(query, webgl1.QUERY_RESULT_AVAILABLE_EXT),
                    result: query => webgl1.isQueryEXT?.(query) === true ? webgl1.getQueryObjectEXT(query, webgl1.QUERY_RESULT_EXT) : 0,
                    remove: query => { if (webgl1.isQueryEXT?.(query) === true) webgl1.deleteQueryEXT(query); }
                };
            }
            return null;
        },

        pollQueries(state) {
            const timer = state?.timer;
            if (!timer || !state.pendingQueries.length) return;
            if (!this.timerStillValid(state)) {
                this.discardTimerState(state, false);
                return;
            }
            let disjoint = false;
            try {
                disjoint = !!timer.gl.getParameter(timer.ext.GPU_DISJOINT_EXT);
            } catch (error) {
                disjoint = true;
            }
            state.gpuDisjoint = disjoint;
            const remaining = [];
            state.pendingQueries.forEach(entry => {
                let available = false;
                try {
                    available = !!timer.available(entry.query);
                } catch (error) {
                    available = true;
                    disjoint = true;
                }
                if (!available) {
                    remaining.push(entry);
                    return;
                }
                try {
                    if (!disjoint) {
                        const gpuMs = Math.max(0, Number(timer.result(entry.query)) || 0) / 1e6;
                        const profile = state.history.find(item => item.frameId === entry.frameId);
                        if (entry.kind === 'frame') {
                            if (profile) {
                                profile.gpuMs = gpuMs;
                                profile.gpuPassesReady = 1;
                                profile.gpuPassesTotal = 1;
                                if (!profile.studio && !profile.budgetObserved) {
                                    profile.budgetObserved = true;
                                    LightflowFrameBudgetController.observe(profile);
                                }
                            }
                        } else if (profile && entry.pass) {
                            entry.pass.gpuMs = gpuMs;
                            const ready = profile.passes.filter(pass => Number.isFinite(pass.gpuMs));
                            profile.gpuPassesReady = ready.length;
                            profile.gpuPassesTotal = profile.passes.length;
                            profile.gpuMs = ready.length === profile.passes.length
                                ? ready.reduce((sum, pass) => sum + pass.gpuMs, 0)
                                : null;
                            if (!profile.studio && Number.isFinite(profile.gpuMs) && !profile.budgetObserved) {
                                profile.budgetObserved = true;
                                LightflowFrameBudgetController.observe(profile);
                            }
                        }
                    }
                } finally {
                    try { timer.remove(entry.query); } catch (error) { /* owned query already gone */ }
                }
            });
            state.pendingQueries = remaining;
        },

        beginFrame(preview) {
            const state = this.getState(preview);
            if (!state) return null;
            LightflowFrameBudgetController.configureForRenderer(state.renderer);
            this.attachContextListeners(state);
            const gl = state.renderer?.getContext?.();
            if (state.contextLost || gl?.isContextLost?.()) {
                this.discardTimerState(state, false);
                return null;
            }
            if (state.timer && !this.timerStillValid(state)) {
                this.discardTimerState(state, false);
            }
            if (state.active) {
                state.depth += 1;
                return state;
            }
            state.active = true;
            state.depth = 1;
            state.frameId += 1;
            state.startedAt = performance.now();
            state.passes = [];
            state.targetSwitches = 0;
            state.timer = state.timer || this.createTimer(state.renderer);
            state.gpuSupported = !!state.timer;
            this.pollQueries(state);
            state.capturePassCpu = this.mode !== 'normal';
            state.captureDetailed = this.mode === 'inspector' || this.mode === 'deep';
            state.frameQuery = null;

            if (
                !state.captureDetailed && state.timer &&
                state.frameId % Math.max(1, this.normalGpuSampleInterval) === 0 &&
                !state.activeGpuQuery
            ) {
                try {
                    const query = state.timer.create();
                    if (query) {
                        state.timer.begin(query);
                        state.activeGpuQuery = query;
                        state.frameQuery = query;
                    }
                } catch (error) {
                    state.activeGpuQuery = null;
                    state.frameQuery = null;
                }
            }

            const renderer = state.renderer;
            // Accumulate the logical frame in every mode. Otherwise normal
            // diagnostics report only the last fullscreen triangle/quad.
            if (renderer.info) {
                state.previousInfoAutoReset = renderer.info.autoReset;
                renderer.info.autoReset = false;
                renderer.info.reset?.();
            }
            if (state.captureDetailed && !state.originalSetRenderTarget && typeof renderer.setRenderTarget === 'function') {
                state.hadOwnSetRenderTarget = Object.prototype.hasOwnProperty.call(renderer, 'setRenderTarget');
                state.originalSetRenderTarget = renderer.setRenderTarget;
                const profilerState = state;
                renderer.setRenderTarget = function lightflowProfiledSetRenderTarget() {
                    profilerState.targetSwitches += 1;
                    return profilerState.originalSetRenderTarget.apply(this, arguments);
                };
            }
            return state;
        },

        getPassResolution(renderer) {
            const target = renderer?.getRenderTarget?.();
            if (target) {
                return {
                    width: Math.max(1, Number(target.width) || 1),
                    height: Math.max(1, Number(target.height) || 1)
                };
            }
            const size = renderer?.getDrawingBufferSize?.(new THREE.Vector2());
            return {
                width: Math.max(1, Math.round(size?.x || renderer?.domElement?.width || 1)),
                height: Math.max(1, Math.round(size?.y || renderer?.domElement?.height || 1))
            };
        },

        runPass(preview, name, callback) {
            if (typeof callback !== 'function') return undefined;
            const state = this.states.get(preview);
            if (!state?.active) return callback();
            if (!state.capturePassCpu) return callback();
            const renderer = state.renderer;
            const info = renderer.info?.render || {};
            const beforeCalls = state.captureDetailed ? Number(info.calls) || 0 : 0;
            const beforeTriangles = state.captureDetailed ? Number(info.triangles) || 0 : 0;
            const beforeLines = state.captureDetailed ? Number(info.lines) || 0 : 0;
            const beforePoints = state.captureDetailed ? Number(info.points) || 0 : 0;
            const resolution = state.captureDetailed ? this.getPassResolution(renderer) : null;
            const startedAt = performance.now();
            const pass = {
                name: String(name || 'unnamed'),
                cpuMs: 0,
                gpuMs: null,
                calls: 0,
                triangles: 0,
                lines: 0,
                points: 0,
                width: resolution?.width ?? null,
                height: resolution?.height ?? null
            };
            let query = null;
            if (state.captureDetailed && state.timer && !state.activeGpuQuery) {
                try {
                    query = state.timer.create();
                    if (query) {
                        state.timer.begin(query);
                        state.activeGpuQuery = query;
                    }
                } catch (error) {
                    query = null;
                    state.activeGpuQuery = null;
                }
            }
            try {
                return callback();
            } finally {
                if (query && state.activeGpuQuery === query) {
                    try {
                        state.timer.end();
                        state.pendingQueries.push({ query, pass, frameId: state.frameId });
                        while (state.pendingQueries.length > 256) {
                            const stale = state.pendingQueries.shift();
                            try { state.timer.remove(stale.query); } catch (error) { /* context already reset */ }
                        }
                    } catch (error) {
                        try { state.timer.remove(query); } catch (removeError) { /* query was rejected */ }
                    }
                    state.activeGpuQuery = null;
                }
                const after = renderer.info?.render || {};
                pass.cpuMs = Math.max(0, performance.now() - startedAt);
                if (state.captureDetailed) {
                    pass.calls = Math.max(0, (Number(after.calls) || 0) - beforeCalls);
                    pass.triangles = Math.max(0, (Number(after.triangles) || 0) - beforeTriangles);
                    pass.lines = Math.max(0, (Number(after.lines) || 0) - beforeLines);
                    pass.points = Math.max(0, (Number(after.points) || 0) - beforePoints);
                }
                state.passes.push(pass);
            }
        },

        endFrame(preview) {
            const state = this.states.get(preview);
            if (!state?.active) return null;
            state.depth = Math.max(0, state.depth - 1);
            if (state.depth > 0) return null;
            const renderer = state.renderer;
            const info = renderer.info?.render || {};
            const profile = {
                frameId: state.frameId,
                timestamp: performance.now(),
                cpuMs: Math.max(0, performance.now() - state.startedAt),
                gpuMs: null,
                gpuSupported: state.gpuSupported,
                gpuDisjoint: state.gpuDisjoint,
                gpuPassesReady: 0,
                gpuPassesTotal: state.passes.length,
                studio: !!(preview?.sa_studio_render_active || window.LightManagerStudioRenderSession),
                calls: Number(info.calls) || 0,
                triangles: Number(info.triangles) || 0,
                lines: Number(info.lines) || 0,
                points: Number(info.points) || 0,
                targetSwitches: state.targetSwitches,
                passes: state.passes
            };
            state.history.unshift(profile);
            if (state.history.length > this.historyLimit) state.history.length = this.historyLimit;
            state.lastProfile = profile;
            state.active = false;
            state.passes = [];

            if (state.frameQuery && state.activeGpuQuery === state.frameQuery) {
                try {
                    state.timer.end();
                    state.pendingQueries.push({
                        kind: 'frame',
                        query: state.frameQuery,
                        frameId: state.frameId
                    });
                } catch (error) {
                    try { state.timer.remove(state.frameQuery); } catch (removeError) { /* query rejected */ }
                }
                state.activeGpuQuery = null;
                state.frameQuery = null;
            }

            if (state.captureDetailed && state.originalSetRenderTarget && renderer.setRenderTarget !== state.originalSetRenderTarget) {
                if (state.hadOwnSetRenderTarget) renderer.setRenderTarget = state.originalSetRenderTarget;
                else delete renderer.setRenderTarget;
            }
            state.originalSetRenderTarget = null;
            if (renderer.info) {
                renderer.info.reset?.();
                renderer.info.autoReset = state.previousInfoAutoReset;
            }
            this.pollQueries(state);
            if (!profile.studio) LightflowFrameBudgetController.observeFrame(profile);
            state.capturePassCpu = false;
            state.captureDetailed = false;
            return profile;
        },

        getProfile(preview = window.Preview?.selected || window.main_preview) {
            const state = this.states.get(preview);
            if (!state) return null;
            this.pollQueries(state);
            return state.lastProfile || null;
        },

        getStatistics(preview = window.Preview?.selected || window.main_preview) {
            const state = this.states.get(preview);
            if (state) this.pollQueries(state);
            const history = state?.history || [];
            const finiteNumber = value => (
                value === null || value === undefined || value === '' || !Number.isFinite(Number(value))
                    ? null
                    : Number(value)
            );
            const percentile = (values, ratio) => {
                const sorted = values.filter(Number.isFinite).sort((left, right) => left - right);
                if (!sorted.length) return null;
                const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil(ratio * sorted.length) - 1));
                return sorted[index];
            };
            const summarize = values => ({
                samples: values.filter(Number.isFinite).length,
                median: percentile(values, 0.5),
                p90: percentile(values, 0.9),
                p95: percentile(values, 0.95),
                p99: percentile(values, 0.99),
                worst: percentile(values, 1.0)
            });
            const passSamples = new Map();
            history.forEach(frame => {
                (frame.passes || []).forEach(pass => {
                    if (!passSamples.has(pass.name)) {
                        passSamples.set(pass.name, {
                            cpu: [], gpu: [], widths: [], heights: [], calls: []
                        });
                    }
                    const samples = passSamples.get(pass.name);
                    samples.cpu.push(finiteNumber(pass.cpuMs));
                    samples.gpu.push(finiteNumber(pass.gpuMs));
                    samples.widths.push(finiteNumber(pass.width));
                    samples.heights.push(finiteNumber(pass.height));
                    samples.calls.push(finiteNumber(pass.calls));
                });
            });
            const frameTimestamps = history
                .map(frame => finiteNumber(frame.timestamp))
                .filter(Number.isFinite)
                .sort((left, right) => left - right);
            const frameIntervals = [];
            for (let index = 1; index < frameTimestamps.length; index++) {
                frameIntervals.push(Math.max(0, frameTimestamps[index] - frameTimestamps[index - 1]));
            }
            return {
                frames: history.length,
                totalFrames: Math.max(0, Number(state?.frameId) || 0),
                gpuSupported: !!state?.gpuSupported,
                gpuDisjoint: !!state?.gpuDisjoint,
                pendingGpuQueries: state?.pendingQueries?.length || 0,
                frameInterval: summarize(frameIntervals),
                frameCpu: summarize(history.map(frame => finiteNumber(frame.cpuMs))),
                frameGpu: summarize(history.map(frame => finiteNumber(frame.gpuMs))),
                passes: Object.fromEntries(Array.from(passSamples, ([name, samples]) => [name, {
                    cpu: summarize(samples.cpu),
                    gpu: summarize(samples.gpu),
                    calls: summarize(samples.calls),
                    physicalWidth: Math.max(0, ...samples.widths.filter(Number.isFinite)),
                    physicalHeight: Math.max(0, ...samples.heights.filter(Number.isFinite))
                }]))
            };
        },

        resetHistory(preview = window.Preview?.selected || window.main_preview, options = {}) {
            const state = this.states.get(preview);
            if (!state) return false;
            if (options.discardPending !== false && state.timer && !state.contextLost) {
                state.pendingQueries.forEach(entry => {
                    try { state.timer.remove(entry.query); } catch (error) { /* query/context already invalid */ }
                });
                state.pendingQueries.length = 0;
            }
            state.history.length = 0;
            state.lastProfile = null;
            return true;
        },

        pruneInactivePreviews(activePreviews) {
            this.states.forEach((state, preview) => {
                if (activePreviews.has(preview)) return;
                this.releasePreview(preview);
            });
        },

        releasePreview(preview, options = {}) {
            if (!preview) return false;
            const state = this.states.get(preview);
            if (!state) return false;
            if (options.contextLost === true) state.contextLost = true;
            this.disposeState(state);
            this.states.delete(preview);
            return true;
        },

        disposeState(state) {
            if (!state) return;
            const renderer = state.renderer;
            if (state.originalSetRenderTarget && renderer?.setRenderTarget !== state.originalSetRenderTarget) {
                if (state.hadOwnSetRenderTarget) renderer.setRenderTarget = state.originalSetRenderTarget;
                else delete renderer.setRenderTarget;
            }
            if (renderer?.info && state.active) {
                renderer.info.autoReset = state.previousInfoAutoReset;
            }
            const timer = state.timer;
            if (timer && state.activeGpuQuery && !state.contextLost && !timer.gl?.isContextLost?.()) {
                try { timer.end(); } catch (error) { /* query/context already invalid */ }
            }
            this.discardTimerState(state, !state.contextLost);
            this.detachContextListeners(state);
        },

        dispose() {
            this.states.forEach(state => this.disposeState(state));
            this.states.clear();
        }
    };

    const LightflowPerformanceAnalyzer = {
        version: 'limiter-analysis-v2',
        minimumCpuSamples: 8,
        minimumGpuSamples: 3,

        finite(value) {
            const number = Number(value);
            return Number.isFinite(number) ? number : null;
        },

        getP95(summary) {
            return this.finite(summary?.p95);
        },

        getPositiveP95(summary) {
            const value = this.getP95(summary);
            return value !== null && value > 0 ? value : null;
        },

        analyze(stats = {}, context = {}) {
            const statistics = stats.logicalFrameStatistics || {};
            const cpuP95 = this.getP95(statistics.frameCpu);
            const rawGpuP95 = this.getPositiveP95(statistics.frameGpu);
            const cpuSamples = Math.max(0, Number(statistics.frameCpu?.samples) || 0);
            const rawGpuSamples = rawGpuP95 !== null
                ? Math.max(0, Number(statistics.frameGpu?.samples) || 0)
                : 0;
            const targetMs = Math.max(1, Number(stats.frameBudget?.targetGpuMs) || (1000 / 60));
            const draws = Math.max(
                0,
                Number(stats.estimatedSceneDrawsPerFrame) || 0,
                Number(stats.rendererCallsLastFrame) || 0
            );
            const triangles = Math.max(0, Number(stats.rendererTrianglesLastFrame) || 0);
            const targetSwitches = Math.max(0, Number(stats.logicalFrameTargetSwitches) || 0);
            const warmupQueue = Math.max(0, Number(stats.warmupQueue) || 0);
            const shadowLightCount = Math.max(0, Number(context.shadowLightCount) || 0);
            const passStatistics = statistics.passes || {};
            const passEntries = Object.entries(passStatistics).map(([name, pass]) => ({
                name,
                gpuP95: this.getPositiveP95(pass?.gpu),
                gpuSamples: Math.max(0, Number(pass?.gpu?.samples) || 0),
                width: Math.max(0, Number(pass?.physicalWidth) || 0),
                height: Math.max(0, Number(pass?.physicalHeight) || 0)
            })).filter(pass => pass.gpuP95 !== null && pass.gpuSamples > 0);
            const sumPasses = predicate => passEntries.reduce((sum, pass) => (
                predicate(pass.name) ? sum + pass.gpuP95 : sum
            ), 0);
            const totalPassGpuP95 = passEntries.reduce((sum, pass) => sum + pass.gpuP95, 0);
            const pixelPassGpuP95 = sumPasses(name => (
                /ao|ssr|atmos|cloud|bloom|composer|composite|resolve|blur|rim|screen|grading|dilation/i.test(name)
            ));
            const shadowPassGpuP95 = sumPasses(name => /shadow/i.test(name));
            const geometryPassGpuP95 = sumPasses(name => /scene|beauty|opaque|surface|geometry|material/i.test(name));
            // A few timer-query implementations publish a zero-filled logical-frame
            // summary before individual pass queries are ready. Zero is not a real
            // GPU duration; use the pass sum so the limiter cannot classify from it.
            const gpuP95 = rawGpuP95 !== null
                ? rawGpuP95
                : (totalPassGpuP95 > 0 ? totalPassGpuP95 : null);
            const gpuSamples = rawGpuP95 !== null
                ? rawGpuSamples
                : passEntries.reduce((maximum, pass) => Math.max(maximum, pass.gpuSamples), 0);
            const gpuSource = rawGpuP95 !== null
                ? 'frame_query'
                : (gpuP95 !== null ? 'pass_sum' : 'unavailable');
            const pixelPassShare = totalPassGpuP95 > 0 ? pixelPassGpuP95 / totalPassGpuP95 : null;
            const shadowPassShare = totalPassGpuP95 > 0 ? shadowPassGpuP95 / totalPassGpuP95 : null;
            const geometryPassShare = totalPassGpuP95 > 0 ? geometryPassGpuP95 / totalPassGpuP95 : null;
            const cpuGpuRatio = cpuP95 !== null && gpuP95 !== null && gpuP95 > 0
                ? cpuP95 / gpuP95
                : null;
            const maxPhysicalPixels = passEntries.reduce(
                (maximum, pass) => Math.max(maximum, pass.width * pass.height),
                0
            );
            const scores = {
                shader_compilation: 0,
                cpu_submission: 0,
                pixel_bandwidth: 0,
                shadow_work: 0,
                gpu_geometry: 0,
                driver_sync: 0,
                balanced: 0
            };
            const score = (name, amount) => { scores[name] += amount; };

            if (warmupQueue > 0) score('shader_compilation', 12);
            if (Number(stats.warmupLastProgramDelta) > 0 && Number(stats.warmupLastDurationMs) > targetMs) {
                score('shader_compilation', 2);
            }
            if (cpuGpuRatio !== null) {
                if (cpuGpuRatio >= 1.5) {
                    score('cpu_submission', 4);
                    score('driver_sync', 2);
                } else if (cpuGpuRatio >= 1.25) {
                    score('cpu_submission', 3);
                } else if (cpuGpuRatio <= 0.67) {
                    score('pixel_bandwidth', 2);
                    score('gpu_geometry', 2);
                } else if (cpuGpuRatio <= 0.8) {
                    score('pixel_bandwidth', 1);
                    score('gpu_geometry', 1);
                } else {
                    score('balanced', 3);
                }
            }
            if (draws >= 5000) score('cpu_submission', 5);
            else if (draws >= 2000) score('cpu_submission', 4);
            else if (draws >= 1000) score('cpu_submission', 3);
            else if (draws >= 500) score('cpu_submission', 1);
            if (targetSwitches >= 80) {
                score('driver_sync', 3);
                score('pixel_bandwidth', 1);
            } else if (targetSwitches >= 40) {
                score('driver_sync', 2);
            } else if (targetSwitches >= 20) {
                score('driver_sync', 1);
            }
            if (pixelPassShare !== null) {
                if (pixelPassShare >= 0.6) score('pixel_bandwidth', 5);
                else if (pixelPassShare >= 0.4) score('pixel_bandwidth', 3);
                else if (pixelPassShare >= 0.25) score('pixel_bandwidth', 1);
            }
            if (maxPhysicalPixels >= 3840 * 2160) score('pixel_bandwidth', 2);
            else if (maxPhysicalPixels >= 1920 * 1080) score('pixel_bandwidth', 1);
            if (shadowPassShare !== null) {
                if (shadowPassShare >= 0.4) score('shadow_work', 6);
                else if (shadowPassShare >= 0.25) score('shadow_work', 4);
                else if (shadowPassShare >= 0.12) score('shadow_work', 2);
            }
            if (shadowLightCount >= 4) score('shadow_work', 3);
            else if (shadowLightCount >= 2) score('shadow_work', 2);
            else if (shadowLightCount === 1) score('shadow_work', 1);
            if (geometryPassShare !== null && geometryPassShare >= 0.55) score('gpu_geometry', 4);
            else if (geometryPassShare !== null && geometryPassShare >= 0.35) score('gpu_geometry', 2);
            if (triangles >= 2000000) score('gpu_geometry', 4);
            else if (triangles >= 500000) score('gpu_geometry', 2);
            if (cpuP95 !== null && cpuP95 > targetMs && gpuP95 === null) {
                score(draws >= 1000 ? 'cpu_submission' : 'driver_sync', 3);
            }
            if (
                cpuP95 !== null && gpuP95 !== null &&
                cpuP95 <= targetMs * 0.9 && gpuP95 <= targetMs * 0.9 &&
                cpuGpuRatio >= 0.8 && cpuGpuRatio <= 1.25
            ) {
                score('balanced', 3);
            }

            const hasEnoughCpu = cpuSamples >= this.minimumCpuSamples;
            const hasEnoughGpu = gpuSamples >= this.minimumGpuSamples;
            const ranked = Object.entries(scores).sort((left, right) => right[1] - left[1]);
            const top = ranked[0] || ['balanced', 0];
            const runnerUp = ranked[1] || ['balanced', 0];
            let id = top[0];
            if (
                warmupQueue <= 0 &&
                (!hasEnoughCpu || (!hasEnoughGpu && draws < 1000))
            ) {
                id = 'collecting';
            } else if (top[1] < 3) {
                id = 'collecting';
            }
            const sampleQuality = Math.min(1, Math.max(
                hasEnoughGpu ? gpuSamples / 16 : 0,
                hasEnoughCpu ? cpuSamples / 60 : 0
            ));
            const scoreMargin = Math.max(0, top[1] - runnerUp[1]);
            let confidence = id === 'collecting'
                ? Math.round(20 + sampleQuality * 20)
                : Math.round(Math.min(96, 48 + top[1] * 4 + scoreMargin * 5) * (0.72 + sampleQuality * 0.28));
            if (!hasEnoughGpu && !['cpu_submission', 'driver_sync', 'shader_compilation', 'collecting'].includes(id)) {
                id = 'collecting';
                confidence = Math.min(confidence, 38);
            }
            const recommendationKeys = {
                collecting: [
                    'shader_architect.performance.limiter.recommend.collect_more',
                    'shader_architect.performance.limiter.recommend.keep_inspector_open'
                ],
                shader_compilation: [
                    'shader_architect.performance.limiter.recommend.finish_warmup',
                    'shader_architect.performance.limiter.recommend.reduce_variants'
                ],
                cpu_submission: [
                    'shader_architect.performance.limiter.recommend.batch',
                    'shader_architect.performance.limiter.recommend.shadow_draws'
                ],
                pixel_bandwidth: [
                    'shader_architect.performance.limiter.recommend.effect_resolution',
                    'shader_architect.performance.limiter.recommend.fuse_passes'
                ],
                shadow_work: [
                    'shader_architect.performance.limiter.recommend.shadow_cache',
                    'shader_architect.performance.limiter.recommend.shadow_bounds'
                ],
                gpu_geometry: [
                    'shader_architect.performance.limiter.recommend.geometry_culling',
                    'shader_architect.performance.limiter.recommend.shadow_lod'
                ],
                driver_sync: [
                    'shader_architect.performance.limiter.recommend.reduce_switches',
                    'shader_architect.performance.limiter.recommend.remove_sync'
                ],
                balanced: [
                    'shader_architect.performance.limiter.recommend.protect_p99',
                    'shader_architect.performance.limiter.recommend.profile_top_pass'
                ]
            }[id] || [];
            const icon = {
                collecting: 'hourglass_top',
                shader_compilation: 'memory',
                cpu_submission: 'developer_board',
                pixel_bandwidth: 'blur_on',
                shadow_work: 'wb_shade',
                gpu_geometry: 'view_in_ar',
                driver_sync: 'sync_problem',
                balanced: 'balance'
            }[id] || 'speed';

            return {
                version: this.version,
                id,
                icon,
                confidence,
                titleKey: `shader_architect.performance.limiter.${id}`,
                summaryKey: `shader_architect.performance.limiter.${id}.summary`,
                recommendationKeys,
                scores,
                metrics: {
                    cpuP95,
                    gpuP95,
                    gpuSource,
                    cpuSamples,
                    gpuSamples,
                    cpuGpuRatio,
                    draws,
                    triangles,
                    targetSwitches,
                    warmupQueue,
                    shadowLightCount,
                    totalPassGpuP95,
                    pixelPassGpuP95,
                    pixelPassShare,
                    shadowPassGpuP95,
                    shadowPassShare,
                    geometryPassGpuP95,
                    geometryPassShare,
                    maxPhysicalPixels,
                    targetMs
                }
            };
        }
    };

    /*
     * The pipeline is the sole Shader Architect owner of Preview.render.
     * Feature managers execute as ordered passes and consume the canonical AO
     * frame resources instead of forming a load-order-dependent wrapper chain.
     */
    const LightflowFramePipeline = {
        patchedPreviews: new Map(),
        passes: new Map(),
        passOverrides: new Map(),
        resourceContracts: LightflowFrameResourceContracts,
        disposed: true,
        graph: null,

        init() {
            this.disposed = false;
            this.graph = LightflowRendererCore.createDefaultGraph();
            this.passes = this.graph.passes;
            // Core passes are declared in the graph even while their legacy
            // implementation is migrated incrementally into pass executors.
            // This gives resource lifetime/budget planning one authoritative
            // view without duplicating the actual render work.
            this.graph.registerPass('main_scene', {
                priority: 50,
                reads: [],
                writes: ['framebuffer'],
                optionalWrites: ['sceneColor', 'sceneDepth', 'sceneSurface', 'sceneEmission'],
                enabled: preview => this.needsCoordinatedFrame(preview)
            });
            this.graph.registerPass('ssr_resolve', {
                priority: 60,
                dependsOn: ['main_scene'],
                reads: ['sceneColor', 'sceneDepth', 'sceneSurface', 'sceneEmission'],
                writes: [
                    'depthMip0', 'depthMip1', 'depthMip2', 'depthMip3',
                    'colorMip0', 'colorMip1', 'colorMip2',
                    'ssrResult', 'ssrHistory'
                ],
                enabled: preview => {
                    const renderer = preview?.renderer;
                    const capabilities = LightflowRendererCore.getCapabilities(renderer);
                    const receiverContractAvailable = !!(
                        renderer?.capabilities?.isWebGL2 &&
                        THREE.WebGLMultipleRenderTargets &&
                        THREE.GLSL3 &&
                        capabilities?.maxDrawBuffers >= 3 &&
                        capabilities?.maxColorAttachments >= 3
                    );
                    return !!(
                        receiverContractAvailable &&
                        this.isPassEnabled('ssr_resolve') &&
                        ScreenSpaceReflectionManager.hasActiveResolveMaterials() &&
                        !ShaderEngine.shouldDeferProjectPreviewEffect?.(1, preview)
                    );
                }
            });
            this.graph.registerPass('ao', {
                priority: 70,
                dependsOn: ['main_scene'],
                reads: ['sceneDepth'],
                optionalReads: ['sceneSurface', 'sceneEmission'],
                writes: ['aoCurrent', 'aoHistory'],
                enabled: preview => (
                    this.isPassEnabled('ao') &&
                    AmbientOcclusionManager.isActiveForPreview(preview)
                )
            });
            // Unwind external wrappers from either load order. A wrapper can
            // only restore itself while it owns preview.render, so alternate
            // the two optional plugins until both chains are peeled.
            window.StudioRender?.detachViewportComposers?.();
            window.LightflowAtmosphere?.detachPreviewWrappers?.();
            window.StudioRender?.detachViewportComposers?.();
            window.LightflowAtmosphere?.detachPreviewWrappers?.();
            this.registerPass('rendercraft_rim', {
                priority: 200,
                reads: ['sceneDepth'],
                writes: ['promoMask', 'promoDilateA', 'promoDilateB', 'framebuffer'],
                enabled: preview => (
                    !preview.sa_studio_render_manual_silhouette &&
                    MinecraftPromotionalSilhouetteManager.getGroups().size > 0
                ),
                execute: preview => MinecraftPromotionalSilhouetteManager.renderSilhouette(preview)
            });
            this.patchAllPreviews(true);
            MinecraftPromotionalSilhouetteManager.patchScreencamPreviewRenders();
            window.dispatchEvent?.(new CustomEvent('lightflow_frame_pipeline_ready'));
        },

        ownsPreview(preview) {
            return !!(!this.disposed && preview && this.patchedPreviews.has(preview));
        },

        getFrameResources(preview) {
            if (this.renderingPreview !== preview) return null;
            return AmbientOcclusionManager.getFrameResources(preview);
        },

        hasActiveResourceConsumer(preview) {
            const sharedResources = new Set([
                'sceneColor', 'sceneDepth', 'sceneSurface', 'sceneEmission', 'sceneNormal'
            ]);
            return Array.from(this.passes.values()).some(pass => {
                if (pass.id === 'main_scene') return false;
                if (!this.isPassEnabled(pass.id)) return false;
                const context = {
                    preview,
                    renderer: preview?.renderer || null,
                    resources: null,
                    pipeline: this
                };
                let dynamicReads = [];
                try {
                    dynamicReads = typeof pass.dynamicReads === 'function'
                        ? pass.dynamicReads(preview, context)
                        : [];
                } catch (error) {
                    warnShaderArchitectOnce(
                        `frame_resource_dynamic_reads_${pass.id}`,
                        `[Lightflow Frame Pipeline] Could not evaluate dynamic reads for ${pass.id}.`,
                        error
                    );
                }
                const reads = [
                    ...pass.reads,
                    ...(Array.isArray(dynamicReads) ? dynamicReads : [])
                ];
                if (!reads.some(resource => sharedResources.has(resource))) return false;
                try {
                    return pass.enabled(preview, context) !== false;
                } catch (error) {
                    warnShaderArchitectOnce(
                        `frame_resource_consumer_${pass.id}`,
                        `[Lightflow Frame Pipeline] Could not evaluate shared resource consumer ${pass.id}.`,
                        error
                    );
                    return false;
                }
            });
        },

        registerPass(id, definition = {}) {
            const key = String(id || '').trim();
            if (!key) return null;
            const entry = {
                id: key,
                priority: Number.isFinite(Number(definition.priority)) ? Number(definition.priority) : 100,
                reads: Array.isArray(definition.reads) ? definition.reads.slice() : [],
                optionalReads: Array.isArray(definition.optionalReads)
                    ? definition.optionalReads.slice()
                    : [],
                writes: Array.isArray(definition.writes) ? definition.writes.slice() : [],
                optionalWrites: Array.isArray(definition.optionalWrites)
                    ? definition.optionalWrites.slice()
                    : [],
                dependsOn: Array.isArray(definition.dependsOn)
                    ? definition.dependsOn.slice()
                    : [],
                dynamicReads: typeof definition.dynamicReads === 'function'
                    ? definition.dynamicReads
                    : null,
                dynamicWrites: typeof definition.dynamicWrites === 'function'
                    ? definition.dynamicWrites
                    : null,
                enabled: typeof definition.enabled === 'function' ? definition.enabled : () => true,
                execute: typeof definition.execute === 'function' ? definition.execute : null
            };
            if (!entry.execute) return null;
            const graphEntry = this.graph?.registerPass(key, entry) || entry;
            this.passes = this.graph?.passes || this.passes;
            if (!this.graph) this.passes.set(key, graphEntry);
            return {
                delete: () => {
                    if (this.graph) this.graph.removePass(key, graphEntry);
                    else if (this.passes.get(key) === graphEntry) this.passes.delete(key);
                }
            };
        },

        registerResource(name, descriptor = {}) {
            if (!this.graph) return null;
            const entry = this.graph.registerResource(name, descriptor);
            if (!entry) return null;
            return {
                entry,
                delete: () => this.graph?.removeResource?.(name, entry)
            };
        },

        setPassEnabled(id, enabled) {
            const key = String(id || '').trim();
            if (!key) return false;
            if (enabled === null || enabled === undefined) this.passOverrides.delete(key);
            else this.passOverrides.set(key, !!enabled);
            ShaderEngine.requestPreviewRender?.({ cause: 'performance_isolation' });
            return true;
        },

        isPassEnabled(id) {
            return this.passOverrides.get(String(id)) !== false;
        },

        resetPassOverrides() {
            this.passOverrides.clear();
            ShaderEngine.requestPreviewRender?.({ cause: 'performance_isolation_reset' });
        },

        executePasses(preview, plan = this.compilePlan(preview)) {
            const context = {
                preview,
                renderer: preview?.renderer || null,
                resources: this.getFrameResources(preview),
                resourceContracts: this.resourceContracts,
                pipeline: this,
                plan
            };
            plan.passes.forEach(pass => {
                    if (typeof pass.execute !== 'function') return;
                    try {
                        LightflowFrameProfiler.runPass(preview, pass.id, () => pass.execute(preview, context));
                    } catch (error) {
                        warnShaderArchitectOnce(
                            `frame_pass_execute_${pass.id}`,
                            `[Lightflow Frame Pipeline] Pass ${pass.id} failed.`,
                            error
                        );
                    }
            });
        },

        compilePlan(preview, options = {}) {
            const profile = options.profile || (
                preview?.sa_studio_render_active || window.LightManagerStudioRenderSession
                    ? 'studio'
                    : 'interactive'
            );
            const extraRequiredResources = [];
            const require = name => {
                if (!extraRequiredResources.includes(name)) extraRequiredResources.push(name);
            };
            const explicitRequiredResources = Array.isArray(options.requiredResources)
                ? options.requiredResources
                    .map(name => String(name || '').trim())
                    .filter(Boolean)
                : [];
            explicitRequiredResources.forEach(require);
            const aoActive = this.isPassEnabled('ao') && AmbientOcclusionManager.isActiveForPreview(preview);
            const rendererCapabilities = LightflowRendererCore.getCapabilities(preview?.renderer);
            const ssrReceiverContractAvailable = !!(
                preview?.renderer?.capabilities?.isWebGL2 &&
                THREE.WebGLMultipleRenderTargets &&
                THREE.GLSL3 &&
                rendererCapabilities?.maxDrawBuffers >= 3 &&
                rendererCapabilities?.maxColorAttachments >= 3
            );
            const ssrActive = ssrReceiverContractAvailable &&
                this.isPassEnabled('ssr_resolve') &&
                ScreenSpaceReflectionManager.hasActiveResolveMaterials() &&
                !ShaderEngine.shouldDeferProjectPreviewEffect?.(1, preview);
            if (aoActive || ssrActive || this.hasActiveResourceConsumer(preview)) {
                require('sceneColor');
                require('sceneDepth');
            }
            if (aoActive) {
                require('aoCurrent');
                require('aoHistory');
            }
            if (ssrActive) {
                // Surface/Emission carry the receiver contract: view-normal +
                // roughness and per-pixel reflection mask. No hidden scene
                // capture is required.
                require('sceneSurface');
                require('sceneEmission');
                require('ssrResult');
            }
            const graphPlan = this.graph.compile(preview, {
                profile,
                isPassEnabled: id => this.isPassEnabled(id),
                extraRequiredResources
            });
            if (graphPlan.requiredResources.includes('sceneNormal') &&
                !graphPlan.requiredResources.includes('sceneSurface')) {
                graphPlan.requiredResources.push('sceneSurface');
            }
            const mrt = !!(
                preview?.renderer?.capabilities?.isWebGL2 &&
                THREE.WebGLMultipleRenderTargets &&
                THREE.GLSL3 &&
                graphPlan.capabilities?.maxDrawBuffers >= 3 &&
                graphPlan.capabilities?.maxColorAttachments >= 3
            );
            const plan = {
                ...graphPlan,
                frame: LightflowFrameProfiler.states.get(preview)?.frameId || 0,
                mrt,
                attachments: [
                    'sceneColor:rgba8',
                    ...(mrt && graphPlan.requiredResources.includes('sceneSurface') ? ['sceneSurface:rgba8'] : []),
                    ...(mrt && graphPlan.requiredResources.includes('sceneEmission') ? ['sceneEmission:rgba8'] : [])
                ]
            };
            this.lastCompiledPlan = plan;
            if (plan.validationErrors.length) {
                warnShaderArchitectOnce(
                    `render_graph_validation_${profile}`,
                    `[Lightflow Renderer] ${profile} render plan contains illegal resources: ${plan.validationErrors.join('; ')}`
                );
            }
            return plan;
        },

        describeGraph() {
            return {
                resources: Array.from(this.graph?.resources?.values?.() || []).map(resource => ({
                    name: resource.name,
                    owner: resource.owner,
                    format: resource.format,
                    scale: resource.scale,
                    external: resource.external,
                    persistent: resource.persistent,
                    aliasOf: resource.aliasOf
                })),
                fixedPasses: [
                    'main_scene',
                    'ssr_color_mip_0..2', 'ssr_hiz_resolve',
                    'ao_evaluate', 'ao_denoise', 'ao_resolve_present'
                ],
                lastCompiledPlan: this.lastCompiledPlan
                    ? {
                        frame: this.lastCompiledPlan.frame,
                        mrt: this.lastCompiledPlan.mrt,
                        attachments: this.lastCompiledPlan.attachments.slice(),
                        profile: this.lastCompiledPlan.profile,
                        requiredResources: this.lastCompiledPlan.requiredResources.slice(),
                        peakEstimatedBytes: this.lastCompiledPlan.peakEstimatedBytes,
                        physicalResourceCount: this.lastCompiledPlan.physicalResourceCount,
                        validationErrors: this.lastCompiledPlan.validationErrors.slice(),
                        passes: this.lastCompiledPlan.passes.map(pass => pass.id)
                    }
                    : null,
                registeredPasses: Array.from(this.passes.values())
                    .sort((left, right) => left.priority - right.priority)
                    .map(pass => ({
                        id: pass.id,
                        priority: pass.priority,
                        dependsOn: pass.dependsOn?.slice?.() || [],
                        reads: pass.reads.slice(),
                        optionalReads: pass.optionalReads?.slice?.() || [],
                        writes: pass.writes.slice(),
                        optionalWrites: pass.optionalWrites?.slice?.() || [],
                        dynamicReads: typeof pass.dynamicReads === 'function',
                        dynamicWrites: typeof pass.dynamicWrites === 'function'
                    }))
            };
        },

        needsCoordinatedFrame(preview) {
            if (preview?.sa_studio_render_active || window.LightManagerStudioRenderSession) return true;
            if (ShaderEngine.shouldApplyShaderArchitectMaterials?.()) return true;
            if (ScreenAccessManager.hasActiveMaterials()) return true;
            if (AmbientOcclusionManager.settings.enabled && AmbientOcclusionManager.hasLightflowMaterial()) return true;
            if (ScreenSpaceReflectionManager.hasActiveReflectiveMaterials()) return true;
            const context = { preview, renderer: preview?.renderer || null, resources: null, pipeline: this };
            return Array.from(this.passes.values()).some(pass => {
                if (pass.id === 'main_scene') return false;
                if (!this.isPassEnabled(pass.id)) return false;
                try { return pass.enabled(preview, context) !== false; }
                catch (error) { return false; }
            });
        },

        patchAllPreviews() {
            if (this.disposed) return;
            const active = collectShaderArchitectRenderPreviews();
            ScreenAccessManager.pruneInactivePreviews(active);
            ScreenSpaceReflectionManager.pruneInactivePreviews(active);
            AmbientOcclusionManager.pruneInactivePreviews(active);
            MinecraftPromotionalSilhouetteManager.pruneInactivePreviews(active);
            LightflowFrameProfiler.pruneInactivePreviews(active);
            this.patchedPreviews.forEach((record, preview) => {
                if (active.has(preview)) return;
                if (preview?.render === record.patchedRender) preview.render = record.originalRender;
                this.patchedPreviews.delete(preview);
            });
            active.forEach(preview => this.patchPreview(preview));
        },

        patchPreview(preview) {
            if (this.disposed || !preview?.renderer || this.patchedPreviews.has(preview)) return;
            const originalRender = preview.render;
            if (typeof originalRender !== 'function') return;
            const pipeline = this;
            const patchedRender = function lightflowFramePipelineRender() {
                return pipeline.renderFrame(this, originalRender, arguments);
            };
            preview.render = patchedRender;
            this.patchedPreviews.set(preview, { originalRender, patchedRender });
        },

        renderFrame(preview, originalRender, args, options = {}) {
            ShaderEngine.markProjectInteractiveFrame?.();
            window.LightflowAtmosphere?.prepareSurfaceFog?.(preview);
            const explicitRequiredResources = Array.isArray(options.requiredResources)
                ? options.requiredResources
                    .map(name => String(name || '').trim())
                    .filter(Boolean)
                : [];
            const externalSharedFrameRequested = !!(
                options.external &&
                explicitRequiredResources.some(name => (
                    name === 'sceneColor' ||
                    name === 'sceneDepth' ||
                    name === 'sceneSurface' ||
                    name === 'sceneNormal' ||
                    name === 'sceneEmission'
                ))
            );

            // Phase 1.5: Studio Render owns one offscreen preview/context. Do not
            // keep every other Blockbench preview issuing full Lightflow frames in
            // parallel while that renderer is processing high-resolution tiles.
            // On ANGLE/D3D11 this multiplied GPU pressure across contexts and a
            // device reset invalidated every context at once. The other previews
            // keep their last presented image and are redrawn when Studio releases
            // its ownership flag.
            if (
                window.LightManagerStudioRenderSession &&
                window.LightManagerStudioRenderPreview &&
                preview !== window.LightManagerStudioRenderPreview
            ) {
                return undefined;
            }

            // Phase 1.6: the warm-up barrier must run before the
            // needsCoordinatedFrame() fast path. During the QUEUED window the
            // viewport can still be in classic/Textured mode, so the old order
            // bypassed the pipeline entirely and allowed two real preview frames
            // to discover five cold programs before COMPILING began.
            const firstPreviewDrawPending = !!(
                ShaderEngine.shaderWarmupProgressSession?.firstPreviewDrawPending &&
                !ShaderEngine.shaderWarmupProgressSession?.firstPreviewDrawRenderAuthorized
            );
            if (ShaderEngine.shouldDeferPreviewRenderForShaderWarmup?.() || firstPreviewDrawPending) {
                ShaderEngine.pendingShaderWarmupRender = true;
                return undefined;
            }

            if (!externalSharedFrameRequested && !this.needsCoordinatedFrame(preview)) {
                return originalRender.apply(preview, args);
            }
            const warmupCoverageAudit = ShaderEngine.beginVisibleFrameWarmupAudit?.(preview);
            const renderRequestEpoch = ShaderEngine.previewRenderRequestEpoch;
            let completedFrame = false;
            const artKeyManager = window.LightManagerArtKeys;
            let previousArtKeyFrame;
            let artKeyFrameStarted = false;
            const profilerState = LightflowFrameProfiler.beginFrame(preview);
            this.renderingPreview = preview;
            try {
                if (ShaderEngine.shouldDeferPreviewRenderForShaderWarmup?.()) {
                    ShaderEngine.pendingShaderWarmupRender = true;
                    return undefined;
                }
                if (artKeyManager?.beginFrame) {
                    previousArtKeyFrame = artKeyManager.beginFrame();
                    artKeyFrameStarted = true;
                }
                const plan = this.compilePlan(preview, {
                    profile: options.profile || undefined,
                    requiredResources: explicitRequiredResources
                });

                LightflowFrameProfiler.runPass(preview, 'frame_prepare', () => {
                    ShaderEngine.validateRenderBatchesBeforeRender?.();
                    ScreenSpaceReflectionManager.preparePreviewForRender(preview, {
                        studio: !!preview.sa_studio_render_active
                    });
                });

                const screenAccessMaterials = ScreenAccessManager.collectActiveMaterials();
                if (!screenAccessMaterials.length) {
                    ScreenAccessManager.releasePreview(preview);
                }

                const allReflectiveMaterials = ScreenSpaceReflectionManager.collectActiveMaterials();
                const resolveMaterials = allReflectiveMaterials.filter(
                    material => material?.sa_uses_ssr_resolve_pass === true
                );
                const legacyInlineMaterials = allReflectiveMaterials.filter(
                    material => material?.sa_uses_ssr_resolve_pass !== true
                );
                const effectDeferred = ShaderEngine.shouldDeferProjectPreviewEffect?.(1, preview);
                const frameCapabilities = LightflowRendererCore.getCapabilities(preview?.renderer);
                const ssrReceiverContractAvailable = !!(
                    preview?.renderer?.capabilities?.isWebGL2 &&
                    THREE.WebGLMultipleRenderTargets &&
                    THREE.GLSL3 &&
                    frameCapabilities?.maxDrawBuffers >= 3 &&
                    frameCapabilities?.maxColorAttachments >= 3
                );
                const ssrActive = ssrReceiverContractAvailable &&
                    this.isPassEnabled('ssr_resolve') &&
                    resolveMaterials.length > 0 && !effectDeferred;
                const legacySsrActive = legacyInlineMaterials.length > 0 && !effectDeferred;
                const renderMain = () => {
                    if (!legacySsrActive) {
                        return LightflowFrameProfiler.runPass(preview, 'main_scene', () => (
                            ScreenAccessManager.renderWithFrameLockedCapture(
                                preview,
                                screenAccessMaterials,
                                () => originalRender.apply(preview, args)
                            )
                        ));
                    }
                    // Compatibility only: legacy Lightflow/PBR families still
                    // contain inline SSR. Rendercraft v4 never enters this path.
                    preview.controls?.update?.();
                    const studioFrame = !!(
                        preview.sa_studio_render_active ||
                        window.LightManagerStudioRenderSession
                    );
                    const previousFrame = studioFrame
                        ? null
                        : AmbientOcclusionManager.getPreviousFrameResources(preview);
                    const reusedHistory = ScreenSpaceReflectionManager.useSharedPreviousFrame(
                        preview,
                        legacyInlineMaterials,
                        previousFrame
                    );
                    if (!reusedHistory) {
                        LightflowFrameProfiler.runPass(preview, 'legacy_ssr_capture', () => {
                            ScreenSpaceReflectionManager.capturePreview(preview, legacyInlineMaterials);
                        });
                    }
                    return LightflowFrameProfiler.runPass(preview, 'main_scene', () => (
                        ScreenAccessManager.renderWithFrameLockedCapture(
                            preview,
                            screenAccessMaterials,
                            () => preview.renderer.render(Canvas.scene, preview.camera)
                        )
                    ));
                };

                const aoActive = this.isPassEnabled('ao') &&
                    AmbientOcclusionManager.isActiveForPreview(preview);
                const needsSharedFrame = aoActive || ssrActive ||
                    externalSharedFrameRequested || this.hasActiveResourceConsumer(preview);
                const result = needsSharedFrame
                    ? AmbientOcclusionManager.renderFrame(preview, renderMain, {
                        applyAO: aoActive,
                        plan,
                        preComposite: ssrActive
                            ? resources => ScreenSpaceReflectionManager.renderPass(
                                preview,
                                resources,
                                resolveMaterials
                            )
                            : null
                    })
                    : renderMain();
                ShaderEngine.scheduleProjectPreviewStageAdvance?.(preview);

                if (!ShaderEngine.shouldDeferProjectPreviewEffect?.(3, preview)) {
                    this.executePasses(preview, plan);
                }
                if (typeof options.onFrameResources === 'function') {
                    const resources = this.getFrameResources(preview);
                    if (!resources) {
                        throw new Error('[Lightflow Renderer] Requested transient frame resources are unavailable.');
                    }
                    LightflowFrameProfiler.runPass(preview, 'external_frame_consumer', () => (
                        options.onFrameResources(resources, {
                            preview,
                            renderer: preview.renderer,
                            plan,
                            profile: options.profile || 'studio',
                            frameId: resources.frameId,
                            lifetime: 'callback_only'
                        })
                    ));
                }
                completedFrame = true;
                return result;
            } finally {
                if (artKeyFrameStarted) artKeyManager.endFrame(previousArtKeyFrame);
                if (completedFrame && !options.external && !preview.sa_studio_render_active &&
                    !window.LightManagerStudioRenderSession) {
                    ShaderEngine.recordCompletedPreviewRender(preview, renderRequestEpoch);
                }
                if (this.renderingPreview === preview) this.renderingPreview = null;
                if (profilerState) LightflowFrameProfiler.endFrame(preview);
                ShaderEngine.completeVisibleFrameWarmupAudit?.(warmupCoverageAudit, preview);
            }
        },

        renderExternal(preview, options = {}) {
            if (!preview?.renderer) return undefined;
            if (this.disposed) this.init();
            this.patchPreview(preview);
            const record = this.patchedPreviews.get(preview);
            if (!record?.originalRender) {
                throw new Error('[Lightflow Renderer] Could not resolve the host Preview.render entry point.');
            }
            const profile = options.profile || 'studio';
            return this.renderFrame(preview, record.originalRender, [], {
                ...options,
                profile,
                external: true
            });
        },

        releaseExternal(preview, options = {}) {
            if (!preview?.renderer) return null;
            if (this.renderingPreview === preview) {
                throw new Error('[Lightflow Renderer] Cannot release an external Preview while it is rendering.');
            }
            const capabilities = LightflowRendererCore.getCapabilities(preview.renderer);
            const contextLost = options.contextLost === true || !!capabilities?.lost;
            const hibernate = options.hibernate === true && !contextLost;
            const released = {
                contextLost,
                hibernated: hibernate,
                screenAccess: ScreenAccessManager.releasePreview(preview, { contextLost }),
                ssr: hibernate
                    ? ScreenSpaceReflectionManager.suspendPreview(preview)
                    : ScreenSpaceReflectionManager.releasePreview(preview, { contextLost }),
                ao: hibernate
                    ? AmbientOcclusionManager.suspendPreview(preview)
                    : AmbientOcclusionManager.releasePreview(preview, { contextLost }),
                promotionalSilhouette: hibernate
                    ? MinecraftPromotionalSilhouetteManager.suspendPreview(preview)
                    : MinecraftPromotionalSilhouetteManager.releasePreview(preview, { contextLost }),
                atmosphere: hibernate
                    ? window.LightflowAtmosphere?.suspendPreview?.(preview) ?? false
                    : window.LightflowAtmosphere?.releasePreview?.(preview, { contextLost }) ?? false,
                profiler: LightflowFrameProfiler.releasePreview(preview, { contextLost })
            };
            const record = this.patchedPreviews.get(preview);
            if (record) {
                if (preview.render === record.patchedRender) preview.render = record.originalRender;
                this.patchedPreviews.delete(preview);
            }
            released.pipelinePatch = !!record;
            released.pool = options.trimPool === false
                ? null
                : LightflowRendererCore.trimResourcePool(preview.renderer, { contextLost });
            return released;
        },

        getCapabilities(previewOrRenderer, options = {}) {
            const renderer = previewOrRenderer?.renderer || previewOrRenderer || null;
            return LightflowRendererCore.getCapabilities(renderer, options);
        },

        getPassShaderSource(material, passDefinition = {}) {
            return LightflowRendererCore.getPassShaderSource(material, passDefinition);
        },

        dispose() {
            if (this.disposed) return;
            this.disposed = true;
            this.patchedPreviews.forEach((record, preview) => {
                if (preview?.render === record.patchedRender) preview.render = record.originalRender;
            });
            this.patchedPreviews.clear();
            this.passes.clear();
            this.graph = null;
            this.passOverrides.clear();
            LightflowFrameProfiler.dispose();
            // The renderer core installs native context listeners outside of
            // Preview.render ownership. They must be torn down explicitly or
            // plugin reloads stack closures from old Shader Architect copies.
            LightflowRendererCore.disposeAllRenderers();
            window.dispatchEvent?.(new CustomEvent('lightflow_frame_pipeline_disposed'));
        }
    };

    /*
     * Animation is a runtime pose stream. It must never masquerade as a
     * topology edit: render batches, shader permutations and material recipes
     * are structural, while matrices/lights/runtime uniforms are temporal.
     */
    const LightflowAnimationRuntime = {
        initialized: false,
        active: false,
        planDirty: true,
        planRevision: 0,
        sceneMotionEpoch: 0,
        frameIndex: 0,
        lastTimelineTime: null,
        stableIds: new Map(),
        nextStableId: 1,
        listeners: [],
        plan: null,
        frameContext: Object.seal({
            timelineTime: 0,
            realTime: 0,
            delta: 0,
            frameIndex: 0,
            mode: 'viewport',
            continuity: 'first',
            studioFrozenTime: null
        }),
        metrics: {
            framesEvaluated: 0,
            motionFrames: 0,
            poseCpuMs: 0,
            animatedTargets: 0,
            changedTargets: 0,
            matrixBytesUploaded: 0,
            totalMatrixBytesUploaded: 0,
            poseCpuTotalMs: 0,
            hostRenderReuses: 0,
            scheduledPreviewRenders: 0,
            structuralRebuildsDuringPose: 0,
            shadowInvalidations: 0,
            aoInvalidations: 0,
            ssrHistoryRejects: 0
        },

        getStableId(uuid) {
            const key = String(uuid || '');
            if (!key) return 0;
            if (!this.stableIds.has(key)) this.stableIds.set(key, this.nextStableId++);
            return this.stableIds.get(key);
        },

        getAnimations() {
            return typeof Animation !== 'undefined' && Array.isArray(Animation.all)
                ? Animation.all.filter(Boolean)
                : [];
        },

        resolveAnimatedObject(uuid) {
            const node = window.OutlinerNode?.uuids?.[uuid] || null;
            const object = node?.mesh || window.Project?.nodes_3d?.[uuid] || null;
            return { node, object };
        },

        getAnimatorChannels(animator) {
            const channels = new Set();
            (animator?.keyframes || []).forEach(keyframe => {
                const channel = String(keyframe?.channel || '').trim();
                if (channel) channels.add(channel);
            });
            if (!channels.size && animator) {
                ['position', 'rotation', 'scale', 'color', 'intensity', 'visibility']
                    .forEach(channel => {
                        if (Array.isArray(animator[channel]) && animator[channel].length) {
                            channels.add(channel);
                        }
                    });
            }
            return Array.from(channels);
        },

        classifyAnimator(uuid, animator) {
            const resolved = this.resolveAnimatedObject(uuid);
            const channels = this.getAnimatorChannels(animator);
            const node = resolved.node;
            const isLight = !!(
                node && (
                    node.type === 'light' ||
                    (typeof LightElement !== 'undefined' && node instanceof LightElement)
                )
            );
            const isElement = !!node && isShaderElement(node);
            return {
                uuid,
                id: this.getStableId(uuid),
                animator,
                node,
                object: resolved.object,
                channels,
                kind: isLight ? 'light' : isElement ? 'element' : 'rigid_domain'
            };
        },

        collectDynamicElementUUIDs(animations) {
            const elementUUIDs = new Set(
                getAllShaderElements().map(element => element?.uuid).filter(Boolean)
            );
            const dynamic = new Set();
            animations.forEach(animation => {
                Object.keys(animation?.animators || {}).forEach(uuid => {
                    const animator = animation.animators[uuid];
                    if (!animator || !(animator.keyframes || []).length) return;
                    if (elementUUIDs.has(uuid)) dynamic.add(uuid);
                });
            });
            return dynamic;
        },

        collectNonInstancedDynamicElementUUIDs(animations) {
            const elementUUIDs = new Set(
                getAllShaderElements().map(element => element?.uuid).filter(Boolean)
            );
            const nonInstanced = new Set();
            animations.forEach(animation => {
                Object.keys(animation?.animators || {}).forEach(uuid => {
                    const animator = animation.animators[uuid];
                    if (!animator || !elementUUIDs.has(uuid)) return;
                    if (this.getAnimatorChannels(animator).includes('scale')) nonInstanced.add(uuid);
                });
            });
            return nonInstanced;
        },

        applyDynamicClassification(dynamicUUIDs) {
            if (!ShaderEngine || ShaderEngine.isUnloading) return false;
            const dynamicElements = getAllShaderElements().filter(element => (
                element?.uuid && dynamicUUIDs.has(element.uuid)
            ));
            let changed = false;
            dynamicElements.forEach(element => {
                if (ShaderEngine.renderBatchDynamicElements.has(element)) return;
                ShaderEngine.renderBatchDynamicElements.add(element);
                changed = true;
            });
            if (changed && ShaderEngine.renderBatches.size) {
                ShaderEngine.releaseRenderBatches();
                ShaderEngine.rebuildRenderBatches();
            }
            return changed;
        },

        updateBindingWorldMatrices(bindings) {
            // Only matrices used by this pose snapshot are needed here. Calling
            // updateMatrixWorld(true) on each animated bone recursively revisits
            // every descendant (including static meshes) for every ancestor.
            // Resolve each required ancestor once, in parent-first order; Three's
            // normal render traversal remains responsible for other descendants.
            const updated = new Set();
            const ancestors = [];
            bindings.forEach(binding => {
                let object = binding.object;
                while (object && !updated.has(object)) {
                    ancestors.push(object);
                    updated.add(object);
                    object = object.parent;
                }
                while (ancestors.length) {
                    const ancestor = ancestors.pop();
                    if (typeof ancestor.updateWorldMatrix === 'function') {
                        ancestor.updateWorldMatrix(false, false);
                    } else {
                        ancestor.updateMatrixWorld?.(true);
                    }
                }
            });
        },

        compileBindingPlan(force = false) {
            if (!force && !this.planDirty && this.plan) return this.plan;
            const animations = this.getAnimations();
            const animation = (typeof Animation !== 'undefined' && Animation.selected) || animations[0] || null;
            const bindings = [];
            Object.keys(animation?.animators || {}).forEach(uuid => {
                const animator = animation.animators[uuid];
                if (!animator || !(animator.keyframes || []).length) return;
                const binding = this.classifyAnimator(uuid, animator);
                if (binding.object) bindings.push(binding);
            });
            const matrices = new Float32Array(bindings.length * 16);
            const previousMatrices = new Float32Array(bindings.length * 16);
            // Matrix4 uses doubles. Keep an unrounded comparison snapshot, while
            // preserving the existing Float32 buffers for GPU pose consumers.
            // Otherwise 100.1 differs from its stored Float32 value by > 1e-6
            // forever, invalidating shadows/AO/SSR even while the pose is still.
            const sourceMatrices = new Float64Array(bindings.length * 16);
            const stableTargetIds = new Uint32Array(bindings.length);
            this.updateBindingWorldMatrices(bindings);
            bindings.forEach((binding, index) => {
                const elements = binding.object.matrixWorld?.elements || [];
                const offset = index * 16;
                for (let component = 0; component < 16; component++) {
                    const value = Number(elements[component]) || 0;
                    matrices[offset + component] = value;
                    previousMatrices[offset + component] = value;
                    sourceMatrices[offset + component] = value;
                }
                stableTargetIds[index] = binding.id;
            });
            const dynamicElementUUIDs = this.collectDynamicElementUUIDs(animations);
            const nonInstancedDynamicElementUUIDs = this.collectNonInstancedDynamicElementUUIDs(animations);
            ShaderEngine.renderBatchNonInstancedDynamicElements.clear();
            getAllShaderElements().forEach(element => {
                if (nonInstancedDynamicElementUUIDs.has(element?.uuid)) {
                    ShaderEngine.renderBatchNonInstancedDynamicElements.add(element);
                }
            });
            this.applyDynamicClassification(dynamicElementUUIDs);
            this.plan = {
                revision: ++this.planRevision,
                animation,
                bindings,
                matrices,
                previousMatrices,
                sourceMatrices,
                stableTargetIds,
                dynamicElementUUIDs,
                nonInstancedDynamicElementUUIDs
            };
            this.planDirty = false;
            this.metrics.animatedTargets = bindings.length;
            return this.plan;
        },

        getContinuity(time, playing) {
            if (!Number.isFinite(this.lastTimelineTime)) return 'first';
            const delta = time - this.lastTimelineTime;
            if (!playing) return Math.abs(delta) > 0.000001 ? 'scrub' : 'continuous';
            if (delta < -0.000001) return 'loop';
            if (Math.abs(delta) > 0.25) return 'seek';
            return 'continuous';
        },

        flush(event = {}) {
            if (!this.initialized || ShaderEngine?.isUnloading) return false;
            const startedAt = performance.now();
            this.metrics.framesEvaluated++;
            const plan = this.compileBindingPlan();
            window.LightManagerFlushAnimatedLights?.({
                render: !(event?.in_loop === true && window.Timeline?.playing === true)
            });
            const time = Number(window.Timeline?.time) || 0;
            const playing = !!window.Timeline?.playing;
            const continuity = this.getContinuity(time, playing);
            let changedTargets = 0;
            const changedElementUUIDs = new Set();
            let animatedCasterMoved = false;
            this.updateBindingWorldMatrices(plan.bindings);
            plan.bindings.forEach((binding, index) => {
                const object = binding.object;
                const source = object?.matrixWorld?.elements;
                if (!source) return;
                const offset = index * 16;
                let changed = false;
                for (let component = 0; component < 16; component++) {
                    const next = Number(source[component]) || 0;
                    const previous = plan.matrices[offset + component];
                    plan.previousMatrices[offset + component] = previous;
                    plan.matrices[offset + component] = next;
                    if (Math.abs(next - plan.sourceMatrices[offset + component]) > 0.000001) changed = true;
                    plan.sourceMatrices[offset + component] = next;
                }
                if (!changed) return;
                changedTargets++;
                if (binding.kind === 'element' && binding.uuid) {
                    changedElementUUIDs.add(binding.uuid);
                }
                if (binding.kind === 'element' && binding.node?.[ELEMENT_CAST_SHADOW_PROP] !== false) {
                    animatedCasterMoved = true;
                }
            });

            const realTime = performance.now() * 0.001;
            const previousRealTime = Number(this.frameContext.realTime) || realTime;
            this.frameContext.timelineTime = time;
            this.frameContext.realTime = realTime;
            this.frameContext.delta = Math.max(0, realTime - previousRealTime);
            this.frameContext.frameIndex = ++this.frameIndex;
            this.frameContext.mode = event?.studio ? 'studio' : 'viewport';
            this.frameContext.continuity = continuity;
            this.frameContext.studioFrozenTime = Number.isFinite(Number(event?.studioFrozenTime))
                ? Number(event.studioFrozenTime)
                : null;
            this.lastTimelineTime = time;

            if (changedTargets > 0) {
                this.metrics.motionFrames++;
                this.sceneMotionEpoch++;
                ShaderEngine.updateDynamicInstanceBatches?.(changedElementUUIDs);
                // A directly animated element normally lives on the dynamic path
                // and an animated group normally owns its retained static batch.
                // Mark validation dirty as a correctness fallback for animation
                // starts, controller changes and scrubbing that bypass the usual
                // timeline lifecycle events. The render hook performs the cheap
                // signature check before deciding whether a rebuild is necessary.
                ShaderEngine.markRenderBatchValidationDirty?.();
                AmbientOcclusionManager.invalidateMotion?.(this.sceneMotionEpoch);
                ScreenSpaceReflectionManager.invalidateCapture?.();
                MinecraftPromotionalSilhouetteManager.invalidateMotion?.(this.sceneMotionEpoch);
                this.metrics.aoInvalidations++;
                if (animatedCasterMoved) {
                    window.LightManagerMarkShadowsDirty?.();
                    this.metrics.shadowInvalidations++;
                }
            }
            const animatedVisibilityMayChange = plan.bindings.some(binding => (
                binding.channels.includes('visibility')
            ));
            if (animatedVisibilityMayChange) {
                // Visibility animation does not change matrix values, so it needs
                // its own batch validation signal or baked members can remain in
                // their previous visible state indefinitely.
                ShaderEngine.markRenderBatchValidationDirty?.();
            }
            if (changedTargets > 0 || animatedVisibilityMayChange) {
                // Blockbench's native animate() loop calls Timeline.loop(), which
                // dispatches display_animation_frame with in_loop=true, and then
                // renders every connected Preview in the same host frame. Queueing
                // another preview.render() here produced a second logical frame on
                // the following RAF and destabilized high-refresh playback. Scrubs
                // and external animation evaluations still need an explicit render.
                const nativeHostRenderPending = event?.in_loop === true && playing && !event?.studio;
                if (nativeHostRenderPending) {
                    this.metrics.hostRenderReuses++;
                } else {
                    ShaderEngine.requestPreviewRender?.({ cause: 'animation_pose' });
                    this.metrics.scheduledPreviewRenders++;
                }
            }
            this.metrics.changedTargets = changedTargets;
            this.metrics.matrixBytesUploaded = changedTargets * 16 * 4;
            this.metrics.totalMatrixBytesUploaded += this.metrics.matrixBytesUploaded;
            this.metrics.poseCpuMs = Math.max(0, performance.now() - startedAt);
            this.metrics.poseCpuTotalMs += this.metrics.poseCpuMs;
            return changedTargets > 0;
        },

        markPlanDirty() {
            this.planDirty = true;
            ShaderEngine?.markRenderBatchValidationDirty?.();
        },

        init() {
            if (this.initialized) return;
            this.initialized = true;
            const listen = (event, callback) => {
                const handle = Blockbench.on(event, callback);
                if (handle) this.listeners.push(handle);
            };
            listen('display_animation_frame', event => this.flush(event));
            listen('timeline_play', () => {
                this.active = true;
                this.compileBindingPlan(true);
            });
            listen('timeline_pause', () => {
                this.active = false;
                window.LightManagerFlushAnimatedLights?.();
            });
            [
                'select_animation', 'add_animation', 'remove_animation',
                'add_keyframe', 'remove_keyframe', 'update_keyframe',
                'select_project', 'undo', 'redo'
            ].forEach(event => listen(event, () => this.markPlanDirty()));
        },

        snapshot() {
            return {
                active: this.active,
                planRevision: this.planRevision,
                sceneMotionEpoch: this.sceneMotionEpoch,
                frameContext: { ...this.frameContext },
                metrics: { ...this.metrics },
                bindings: this.plan?.bindings?.map(binding => ({
                    id: binding.id,
                    uuid: binding.uuid,
                    kind: binding.kind,
                    channels: binding.channels.slice()
                })) || []
            };
        },

        dispose() {
            this.listeners.splice(0).reverse().forEach(listener => listener?.delete?.());
            this.initialized = false;
            this.active = false;
            this.plan = null;
            this.planDirty = true;
            this.lastTimelineTime = null;
        }
    };

    function scheduleShaderWarmupFrame(callback, options = {}) {
        const fallbackMs = Math.max(16, Number(options.fallbackMs) || 120);
        const hiddenDelayMs = options.hiddenDelayMs === undefined
            ? 16
            : Math.max(0, Number(options.hiddenDelayMs) || 0);
        const ticket = {
            animationFrame: null,
            fallbackTimer: null,
            finished: false,
            cancelled: false
        };
        const finish = timestamp => {
            if (ticket.finished || ticket.cancelled) return;
            ticket.finished = true;
            if (ticket.animationFrame !== null && typeof cancelAnimationFrame === 'function') {
                cancelAnimationFrame(ticket.animationFrame);
            }
            if (ticket.fallbackTimer !== null) clearTimeout(ticket.fallbackTimer);
            ticket.animationFrame = null;
            ticket.fallbackTimer = null;
            callback(timestamp);
        };
        const visible = typeof document === 'undefined' || document.visibilityState === 'visible';
        if (visible && typeof requestAnimationFrame === 'function') {
            ticket.animationFrame = requestAnimationFrame(finish);
            ticket.fallbackTimer = setTimeout(() => finish(Date.now()), fallbackMs);
        } else {
            ticket.fallbackTimer = setTimeout(() => finish(Date.now()), hiddenDelayMs);
        }
        return ticket;
    }

    function cancelShaderWarmupFrame(ticket) {
        if (!ticket || ticket.cancelled || ticket.finished) return;
        ticket.cancelled = true;
        if (ticket.animationFrame !== null && typeof cancelAnimationFrame === 'function') {
            cancelAnimationFrame(ticket.animationFrame);
        }
        if (ticket.fallbackTimer !== null) clearTimeout(ticket.fallbackTimer);
        ticket.animationFrame = null;
        ticket.fallbackTimer = null;
    }

    function waitForShaderWarmupFrame(options = {}) {
        return new Promise(resolve => scheduleShaderWarmupFrame(resolve, options));
    }

