                            sa_material_id: {
                                configurable: true,
                                enumerable: false,
                                writable: true,
                                value: ''
                            },
                            sa_material_instance_id: {
                                configurable: true,
                                enumerable: false,
                                writable: true,
                                value: ''
                            },
