                        uvB.fromBufferAttribute(uvAttr, idxB);
                        uvC.fromBufferAttribute(uvAttr, idxC);
                        deltaPos1.subVectors(posB, posA);
                        deltaPos2.subVectors(posC, posA);
                        deltaUv1.subVectors(uvB, uvA);
                        deltaUv2.subVectors(uvC, uvA);
